//! The meta Energy Nexus contract. Every type of its own is generated by
//! ethos-zero from `ethos/signal.ethos` into `src/generated/`, and `build.rs`
//! refuses a committed file that differs from its generation. The Energy
//! vocabulary and the caller envelope are the ordinary contract's, imported
//! by the Ethos and re-exported here.
pub mod generated;
pub use generated::signal::*;

pub use signal_energy_nexus::{
    Baseline, Caller, Credit, Minutes, Name, Override, Percent, Provider, ProviderTarget, Reminder,
    ResetId, Span, Target, Threshold, TimeZone,
    Spent,
};

/// The authored meta Signal; its text is the contract's identity on the wire.
pub const ETHOS: &str = include_str!("../ethos/signal.ethos");

impl signal::Contracted for Call {
    const CONTRACT_SOURCE: &'static str = ETHOS;
}

#[cfg(test)]
mod tests {
    use super::*;
    use signal::{ByteViewable, Restorable, Signal, Signalizable};
    use signal_energy_nexus::{ProcessId, UserId};
    #[test]
    fn validated_binary_round_trip() {
        let value = Call {
            caller: Caller {
                process_id: ProcessId(1),
                user_id: UserId(2),
            },
            input: Input::Configure(Set::RedeemExpiring(Minutes(720))),
        };
        let bytes = value.signalize().unwrap();
        let restored = Signal::<Call>::from(bytes.bytes().to_vec())
            .restore()
            .unwrap();
        assert_eq!(restored, value);
    }

    #[test]
    fn configured_credit_and_spend_round_trip_as_meta_settings() {
        let values = [
            Call {
                caller: Caller {
                    process_id: ProcessId(1),
                    user_id: UserId(2),
                },
                input: Input::Configure(Set::Credit(Credit {
                    provider: Provider::ClaudeApi,
                    granted: signal_energy_nexus::Cents(20_000),
                    starts: signal_energy_nexus::Starts(signal_energy_nexus::Instant(
                        1_795_046_400,
                    )),
                    expires: signal_energy_nexus::Expires(signal_energy_nexus::Instant(
                        1_797_638_400,
                    )),
                    renewal: signal_energy_nexus::Renewal::Monthly,
                    lead_time_option: Some(Minutes(10_080)),
                })),
            },
            Call {
                caller: Caller {
                    process_id: ProcessId(1),
                    user_id: UserId(2),
                },
                input: Input::Configure(Set::Spent(Spent {
                    provider: Provider::ClaudeApi,
                    cents: signal_energy_nexus::Cents(13),
                    at: signal_energy_nexus::At(signal_energy_nexus::Instant(1_795_047_000)),
                })),
            },
        ];
        for value in values {
            let bytes = value.signalize().unwrap();
            let restored = Signal::<Call>::from(bytes.bytes().to_vec())
                .restore()
                .unwrap();
            assert_eq!(restored, value);
        }
    }

    /// The provider polling interval is gone: Energy reads on events, so no
    /// setting names an interval.
    #[cfg(feature = "datom")]
    #[test]
    fn a_polling_interval_no_longer_reads() {
        use datom_codec::{Actualizing, Budget, Potential};
        use protos::ReaderBudget;
        let read = |text: &str| {
            let mut budget = Budget {
                remaining: 256,
                reader: ReaderBudget::try_from(256).unwrap(),
                depth: 0,
                maximum_depth: 32,
            };
            Potential::<Input>::from(text).actualize(&mut budget)
        };
        assert!(read("Configure.Polling.5").is_err());
        assert_eq!(
            read("Configure.RedeemExpiring.720").unwrap(),
            Input::Configure(Set::RedeemExpiring(Minutes(720)))
        );
    }
}
